'use strict';

// MODULES //

var join = require( 'path' ).join;
var basename = require( 'path' ).basename;
var writeFileSync = require( '@stdlib/fs/write-file' ).sync;
var licenseHeader = require( '@stdlib/_tools/licenses/header' );
var currentYear = require( '@stdlib/time/current-year' );
var generateMatchesTable = require( './script.js' );


// FUNCTIONS //

/**
* Returns an index for ordering input types by approximate likelihood of use.
*
* @private
* @param {string} dtype - input dtype
* @returns {number} order index
*/
function inputTypeOrderIndex( dtype ) {
	// Prefer float64, then float32, then generic, then signed ints, then unsigned ints, then others...
	switch ( dtype ) { // eslint-disable-line default-case
	case 'float64':
		return 0;
	case 'float32':
		return 1;
	case 'generic':
		return 2;
	case 'int32':
		return 3;
	case 'int16':
		return 4;
	case 'int8':
		return 5;
	case 'uint32':
		return 6;
	case 'uint16':
		return 7;
	case 'uint8':
		return 8;
	case 'uint8c':
		return 9;
	case 'float16':
		return 10;
	case 'complex128':
		return 11;
	case 'complex64':
		return 12;
	case 'complex32':
		return 13;
	}
	return 99;
}

/**
* Groups matches by input data type and reorders by likelihood of use.
*
* @private
* @param {Array} matches - array of match entries
* @returns {Object} object containing grouped matches, ordered input types array, and reordered matches
*/
function groupMatchesByInputType( matches ) {
	var reorderedMatches = [];
	var inputTypes = [];
	var inputType;
	var grouped = {};
	var i;
	var j;

	for ( i = 0; i < matches.length; i++ ) {
		inputType = matches[ i ][ 0 ];
		if ( !grouped[ inputType ] ) {
			grouped[ inputType ] = [];
			inputTypes.push( inputType );
		}
		grouped[ inputType ].push( matches[ i ][ 1 ] );
	}

	// Order input types by preferred usage:
	inputTypes.sort( compare );

	/**
	* Comparison function for input dtype ordering.
	*
	* @private
	* @param {string} a - left dtype
	* @param {string} b - right dtype
	* @returns {number} comparison result
	*/
	function compare( a, b ) {
		return inputTypeOrderIndex( a ) - inputTypeOrderIndex( b );
	}

	for ( i = 0; i < inputTypes.length; i++ ) {
		inputType = inputTypes[ i ];
		for ( j = 0; j < matches.length; j++ ) {
			if ( matches[ j ][ 0 ] === inputType ) {
				reorderedMatches.push( matches[ j ] );
			}
		}
	}

	return {
		'grouped': grouped,
		'inputTypes': inputTypes,
		'reorderedMatches': reorderedMatches
	};
}

/**
* Generates the types.js file content.
*
* @private
* @param {Array} matches - array of match entries
* @param {string} header - license header
* @returns {string} types.js file content
*/
function generateTypesFile( matches, header ) {
	var outputTypes;
	var inputTypes;
	var inputType;
	var grouped;
	var result;
	var jsOut;
	var i;
	var j;

	jsOut = header;
	jsOut += '/*\n';
	jsOut += '* NOTE: this file is only for developer convenience. Upon updating this file, run the `scripts/types.js` file to regenerate the compact types representation.\n';
	jsOut += '*/\n\n';
	jsOut += '/* eslint-disable array-element-newline */\n\n';
	jsOut += '\'use strict\';\n\n';
	jsOut += '// MODULES //\n\n';
	jsOut += 'var dtypes = require( \'@stdlib/ndarray/dtypes\' );\n\n\n';
	jsOut += '// MAIN //\n\n';
	jsOut += 'var types = [\n';

	// Group matches by input dtype...
	result = groupMatchesByInputType( matches );
	grouped = result.grouped;
	inputTypes = result.inputTypes;

	// Generate grouped output with proper formatting and comments...
	for ( i = 0; i < inputTypes.length; i++ ) {
		inputType = inputTypes[ i ];
		outputTypes = grouped[ inputType ];

		// Add comment with input type and count
		jsOut += '\t// ' + inputType + ' (' + outputTypes.length + ')\n';

		for ( j = 0; j < outputTypes.length; j++ ) {
			jsOut += '\tdtypes.' + inputType + ', dtypes.' + outputTypes[ j ];
			if ( i < inputTypes.length - 1 || j < outputTypes.length - 1 ) {
				jsOut += ',\n';
			} else {
				jsOut += '\n';
			}
		}

		// Add blank line between input type groups ( except for the last one )...
		if ( i < inputTypes.length - 1 ) {
			jsOut += '\n';
		}
	}

	jsOut += '];\n\n\n';
	jsOut += '// EXPORTS //\n\n';
	jsOut += 'module.exports = types;\n';
	return jsOut;
}

/**
* Generates the addon.c file content.
*
* @private
* @param {Array} matches - array of match entries
* @param {string} header - license header
* @param {string} basePkg - base package name
* @returns {string} addon.c file content
*/
function generateAddonFile( matches, header, basePkg ) {
	var uniqueIncludes;
	var functionIndex;
	var outputTypes;
	var includeKey;
	var inputType;
	var grouped;
	var result;
	var cOut;
	var i;
	var j;

	// Generate unique includes...
	uniqueIncludes = {};
	for ( i = 0; i < matches.length; i++ ) {
		includeKey = matches[ i ][ 6 ].replace( 'stdlib_base_', '' );
		uniqueIncludes[ '#include "stdlib/math/base/special/' + includeKey + '.h"' ] = true;
	}

	// Group matches by input type and reorder by likelihood of use...
	result = groupMatchesByInputType( matches );
	grouped = result.grouped;
	matches = result.reorderedMatches;

	cOut = header;
	cOut += Object.keys( uniqueIncludes ).join( '\n' ) + '\n';
	cOut += '#include "stdlib/ndarray/base/function_object.h"\n';
	cOut += '#include "stdlib/ndarray/base/napi/unary.h"\n';
	cOut += '#include "stdlib/ndarray/base/unary.h"\n';
	cOut += '#include "stdlib/ndarray/dtypes.h"\n';
	cOut += '#include <stdint.h>\n\n';

	// Define interface name with comment...
	cOut += '// Define an interface name:\n';
	cOut += 'static const char name[] = "stdlib_ndarray_' + basePkg + '";\n\n';

	// Define functions array with comments and grouping...
	cOut += '// Define a list of ndarray functions:\n';
	cOut += 'static ndarrayFcn functions[] = {\n';

	// Add functions with type group comments...
	functionIndex = 0;
	for ( i = 0; i < result.inputTypes.length; i++ ) {
		inputType = result.inputTypes[ i ];
		outputTypes = grouped[ inputType ];

		cOut += '\t// ' + inputType + ' (' + outputTypes.length + ')\n';
		for ( j = 0; j < outputTypes.length; j++ ) {
			cOut += '\t' + matches[ functionIndex ][ 7 ] + ',\n';
			functionIndex += 1;
		}
		cOut += '\n';
	}
	cOut += '};\n\n';

	// Define types array with comments and grouping...
	cOut += '// Define the array of input and output ndarray types:\n';
	cOut += 'static int32_t types[] = {\n';
	functionIndex = 0;
	for ( i = 0; i < result.inputTypes.length; i++ ) {
		inputType = result.inputTypes[ i ];
		outputTypes = grouped[ inputType ];

		cOut += '\t// ' + inputType + ' (' + outputTypes.length + ')\n';
		for ( j = 0; j < outputTypes.length; j++ ) {
			cOut += '\tSTDLIB_NDARRAY_' + matches[ functionIndex ][ 0 ].toUpperCase() + ', STDLIB_NDARRAY_' + matches[ functionIndex ][ 1 ].toUpperCase() + ',\n';
			functionIndex += 1;
		}
		cOut += '\n';
	}
	cOut += '};\n\n';

	// Define data array with comments and grouping...
	cOut += '// Define a list of ndarray function "data" (in this case, callbacks):\n';
	cOut += 'static void *data[] = {\n';
	functionIndex = 0;
	for ( i = 0; i < result.inputTypes.length; i++ ) {
		inputType = result.inputTypes[ i ];
		outputTypes = grouped[ inputType ];

		cOut += '\t// ' + inputType + ' (' + outputTypes.length + ')\n';
		for ( j = 0; j < outputTypes.length; j++ ) {
			cOut += '\t(void *)' + matches[ functionIndex ][ 6 ] + ',\n';
			functionIndex += 1;
		}
		cOut += '\n';
	}
	cOut += '};\n\n';

	// Define function object with detailed comments...
	cOut += '// Create an ndarray function object:\n';
	cOut += 'static const struct ndarrayFunctionObject obj = {\n';
	cOut += '\t// ndarray function name:\n';
	cOut += '\tname,\n\n';
	cOut += '\t// Number of input ndarrays:\n';
	cOut += '\t1,\n\n';
	cOut += '\t// Number of output ndarrays:\n';
	cOut += '\t1,\n\n';
	cOut += '\t// Total number of ndarray arguments (nin + nout):\n';
	cOut += '\t2,\n\n';
	cOut += '\t// Array containing ndarray functions:\n';
	cOut += '\tfunctions,\n\n';
	cOut += '\t// Number of ndarray functions:\n';
	cOut += '\t' + matches.length + ',\n\n';
	cOut += '\t// Array of type "numbers" (as enumerated elsewhere), where the total number of types equals `narrays * nfunctions` and where each set of `narrays` consecutive types (non-overlapping) corresponds to the set of ndarray argument types for a corresponding ndarray function:\n';
	cOut += '\ttypes,\n\n';
	cOut += '\t// Array of void pointers corresponding to the "data" (e.g., callbacks) which should be passed to a respective ndarray function (note: the number of pointers should match the number of ndarray functions):\n';
	cOut += '\tdata\n';
	cOut += '};\n\n';

	// Export the function object...
	cOut += 'STDLIB_NDARRAY_NAPI_MODULE_UNARY( obj )\n';
	return cOut;
}


// MAIN //

/**
* Main execution function.
*
* @private
*/
function main() {
	var basePkg;
	var matches;
	var header;
	var jsOut;
	var cOut;

	// Generate and filter matches table:
	matches = generateMatchesTable();

	// Extract package information (base package name):
	basePkg = basename( join( __dirname, '..' ) );

	// Generate license header:
	header = licenseHeader( 'Apache-2.0', 'js', {
		'year': currentYear(),
		'copyright': 'The Stdlib Authors'
	});
	header += '\n/* This is a generated file. Do not edit directly. */\n';

	// Ensure output directories exist:
	ensureDir( join( __dirname, '../lib' ) );
	ensureDir( join( __dirname, '../src' ) );

	/**
	* Ensures a directory exists.
	*
	* @private
	* @param {string} d - directory path
	*/
	function ensureDir( d ) {
		try {
			writeFileSync( join( d, '.keep' ), '', {
				'encoding': 'utf8'
			});
		} catch ( error ) { // eslint-disable-line no-unused-vars
			// If the directory does not exist, creating a file will fail. Attempt again by creating a placeholder in parent.
		}
	}

	// Generate types.js:
	jsOut = generateTypesFile( matches, header );
	writeFileSync( join( __dirname, '../lib/types.js' ), jsOut, {
		'encoding': 'utf8'
	});

	// Generate addon.c:
	cOut = generateAddonFile( matches, header, basePkg );
	writeFileSync( join( __dirname, '../src/addon.c' ), cOut, {
		'encoding': 'utf8'
	});
}


// MAIN //

main();
